const express = require('express');
const crypto = require('crypto');
const fs = require('fs');

const app = express();
app.use(express.json());

// Key management
const RSA_PUBLIC_KEY = fs.readFileSync('/etc/app/public.pem', 'utf8');
const RSA_PRIVATE_KEY = fs.readFileSync('/etc/app/private.pem', 'utf8');

// Token configuration - RS256 only
const TOKEN_CONFIG = {
  issuer: 'auth-service',
  audience: 'api-service',
  algorithm: 'RS256',
  maxAge: 3600
};

// Minimal user store. Passwords are stored as scrypt hashes with per-user salt.
// Format: { salt: <hex>, hash: <hex> } computed via crypto.scryptSync(password, salt, 64).
const USER_STORE = (() => {
  try {
    return JSON.parse(fs.readFileSync('/etc/app/users.json', 'utf8'));
  } catch (e) {
    return {};
  }
})();

function verifyCredentials(username, password) {
  const record = USER_STORE[username];
  if (!record || !record.salt || !record.hash) return null;

  const salt = Buffer.from(record.salt, 'hex');
  const expected = Buffer.from(record.hash, 'hex');
  let derived;
  try {
    derived = crypto.scryptSync(password, salt, expected.length);
  } catch (e) {
    return null;
  }

  // Constant-time comparison to prevent timing attacks.
  if (derived.length !== expected.length) return null;
  if (!crypto.timingSafeEqual(derived, expected)) return null;

  return { role: record.role || 'user' };
}

function base64UrlEncode(data) {
  return Buffer.from(JSON.stringify(data)).toString('base64url');
}

function base64UrlDecode(str) {
  return JSON.parse(Buffer.from(str, 'base64url').toString());
}

function signToken(payload) {
  const header = { alg: 'RS256', typ: 'JWT' };
  const headerB64 = base64UrlEncode(header);
  const payloadB64 = base64UrlEncode(payload);
  const signingInput = `${headerB64}.${payloadB64}`;

  const sign = crypto.createSign('RSA-SHA256');
  sign.update(signingInput);
  const signature = sign.sign(RSA_PRIVATE_KEY, 'base64url');
  return `${signingInput}.${signature}`;
}

// Dynamic handler registry for extensible claim validation
const claimValidators = new Map();

claimValidators.set('iss', (value) => value === TOKEN_CONFIG.issuer);
claimValidators.set('aud', (value) => value === TOKEN_CONFIG.audience);
claimValidators.set('exp', (value) => {
  const now = Math.floor(Date.now() / 1000);
  return !value || value >= now;
});
claimValidators.set('iat', (value) => {
  const now = Math.floor(Date.now() / 1000);
  return !value || (now - value) <= TOKEN_CONFIG.maxAge;
});

function validateClaims(payload) {
  for (const [claim, validator] of claimValidators) {
    if (!validator(payload[claim])) {
      throw new Error(`Invalid claim: ${claim}`);
    }
  }
}

function verifyToken(token) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Invalid token format');

  const header = base64UrlDecode(parts[0]);
  const payload = base64UrlDecode(parts[1]);
  const signatureProvided = parts[2];

  // CRITICAL: Ignore the header's stated algorithm - always use RS256
  // This prevents algorithm confusion attacks
  if (header.alg !== 'RS256') {
    throw new Error('Only RS256 algorithm is accepted');
  }
  if (header.typ !== 'JWT') {
    throw new Error('Invalid token type');
  }

  // Validate claims using dynamic validators
  validateClaims(payload);

  // Always verify with RSA public key regardless of header
  const signingInput = `${parts[0]}.${parts[1]}`;
  const verify = crypto.createVerify('RSA-SHA256');
  verify.update(signingInput);
  const valid = verify.verify(RSA_PUBLIC_KEY, signatureProvided, 'base64url');

  if (!valid) throw new Error('Invalid signature');
  return payload;
}

// Middleware
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  try {
    req.user = verifyToken(authHeader.slice(7));
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Authentication failed' });
  }
}

// Routes
app.post('/auth/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing credentials' });

  // Verify the supplied credentials before issuing a token.
  const account = verifyCredentials(username, password);
  if (!account) {
    return res.status(401).json({ error: 'Authentication failed' });
  }

  const payload = {
    sub: username,
    iss: TOKEN_CONFIG.issuer,
    aud: TOKEN_CONFIG.audience,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + TOKEN_CONFIG.maxAge,
    role: account.role
  };

  const token = signToken(payload);
  res.json({ token });
});

app.get('/api/admin/users', authenticate, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin access required' });
  }
  res.json({ users: ['alice', 'bob', 'charlie'] });
});

app.get('/api/profile', authenticate, (req, res) => {
  res.json({ user: req.user.sub, role: req.user.role });
});

app.listen(3000);
module.exports = app;
